import{_ as t,o as e,c as o,a2 as r}from"./chunks/framework.BZO4qERu.js";const m=JSON.parse('{"title":"微信(个人号)","description":"","frontmatter":{},"headers":[],"relativePath":"zh/integrations/channels/weixin.md","filePath":"zh/integrations/channels/weixin.md","lastUpdated":1790952322000}'),i={name:"zh/integrations/channels/weixin.md"};function n(l,a,h,s,d,c){return e(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="微信-个人号" tabindex="-1">微信(个人号) <a class="header-anchor" href="#微信-个人号" aria-label="Permalink to &quot;微信(个人号)&quot;">​</a></h1><p>把 Memoh Bot 接入个人微信:扫二维码即可登录,不用手填 token 或 API key。</p><div class="warning custom-block"><p class="custom-block-title">使用限制</p><ul><li>仅支持私聊。</li><li>仅输出纯文本,不渲染 Markdown。</li><li>文本消息按每段最多 4000 字符拆分发送。</li><li>回复按完整消息送达,无流式输出。</li></ul></div><h2 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to &quot;前提条件&quot;">​</a></h2><ul><li>手机上装有微信,并登录 Bot 要使用的账号——登录靠手机扫码确认。</li></ul><h2 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to &quot;步骤&quot;">​</a></h2><h3 id="_1-在-memoh-里添加微信渠道" tabindex="-1">1. 在 Memoh 里添加微信渠道 <a class="header-anchor" href="#_1-在-memoh-里添加微信渠道" aria-label="Permalink to &quot;1. 在 Memoh 里添加微信渠道&quot;">​</a></h3><p>在 Memoh,打开 Bot 的 <strong>平台</strong> 标签页,点 <strong>Add Channel</strong>,选择 <strong>WeChat</strong>。</p><h3 id="_2-扫码登录" tabindex="-1">2. 扫码登录 <a class="header-anchor" href="#_2-扫码登录" aria-label="Permalink to &quot;2. 扫码登录&quot;">​</a></h3><p>在 Memoh:</p><ol><li>点 <strong>Start QR Login</strong>,Memoh 会从微信平台拉取二维码。</li><li>用手机微信扫页面上显示的二维码。</li><li>在手机上确认登录。</li></ol><p>确认后,Memoh 自动保存凭据,渠道随即启用。</p><h2 id="凭据" tabindex="-1">凭据 <a class="header-anchor" href="#凭据" aria-label="Permalink to &quot;凭据&quot;">​</a></h2><p>扫码登录后,会话凭据由 Memoh 自动保存,没有需要手填的字段。可选设置一项:</p><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><strong>Enable Typing</strong></td><td>否</td><td>生成回复时显示「正在输入」状态。</td></tr></tbody></table><h2 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h2><p>二维码登录成功后,渠道自动启用。在微信里私聊给 Bot 发送 <code>/help</code>,Bot 回复命令列表,说明渠道已接通。</p><h2 id="停用与更换凭据" tabindex="-1">停用与更换凭据 <a class="header-anchor" href="#停用与更换凭据" aria-label="Permalink to &quot;停用与更换凭据&quot;">​</a></h2><p>随时可在 Bot 的 <strong>平台</strong> 标签页停用或移除该渠道。需要重新登录时,再次点 <strong>Start QR Login</strong> 走一遍扫码流程即可。</p><h2 id="faq" tabindex="-1">常见问题 <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;常见问题 {#faq}&quot;">​</a></h2><h3 id="qr-expired" tabindex="-1">还没扫,二维码就过期了 <a class="header-anchor" href="#qr-expired" aria-label="Permalink to &quot;还没扫,二维码就过期了 {#qr-expired}&quot;">​</a></h3><p>二维码有有效期。再点一次 <strong>Start QR Login</strong>,获取新的二维码。</p>',22)])])}const u=t(i,[["render",n]]);export{m as __pageData,u as default};
